"""First twelve tropical/vector-borne questions: malaria, with 2026 source checks."""
from qbank_authoring import question,ref,finalize
WM=ref('WHO Guidelines for Malaria, September 2026','https://www.who.int/publications/i/item/guidelines-for-malaria/')
SM=ref('CDC: Treatment of Severe Malaria, 2026','https://www.cdc.gov/malaria/hcp/clinical-guidance/iv-artesunate-us.html')
UM=ref('CDC: Treatment of Uncomplicated Malaria, 2026','https://www.cdc.gov/malaria/hcp/clinical-guidance/treatment-of-uncomplicated-malaria.html')
MD=ref('CDC: Rapid Malaria Diagnostics Toolkit, 2026','https://www.cdc.gov/malaria/hcp/rapid-diagnostics/index.html')
MQ=ref('CDC: Malaria Diagnosis and Treatment Quick Reference','https://www.cdc.gov/malaria/php/surveillance/diagnosis-treatment-quick-reference.html')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('A patient with confirmed malaria has impaired consciousness, metabolic acidosis and AKI. Parasitemia is not yet fully quantified. What is the best treatment principle?', 'Manage as severe malaria immediately rather than wait for a high parasite-density threshold',[
 ('Use only oral therapy until density exceeds an arbitrary cutoff','Organ dysfunction already establishes severe illness.'),('Exclude severe malaria if a vivax species is later identified','Severe disease can occur with non-falciparum species.'),('Wait for PCR species confirmation before any treatment','This can create a dangerous delay.')],
 'Severe organ manifestations determine urgency', '**Severe malaria is a medical emergency regardless of whether every laboratory result has returned.**',['Assess airway, glucose, renal function and acid-base state.','Parasite density adds risk information but is not the only severe criterion.'], '**Start parenteral therapy and supportive care promptly.**',['Arrange expert management and serial microscopy.','Investigate alternative or additional causes of organ dysfunction.'],[['Clinical severity','Organ dysfunction'],['Density','Important but not the sole criterion'],['Priority','Immediate severe-malaria management']],[WM,SM],style='clinical_scenario')
q('Which antimalarial is preferred for initial treatment of severe malaria when available?', 'Parenteral artesunate',[
 ('Oral chloroquine alone regardless of resistance or severity','It is not suitable universal severe-malaria treatment.'),('Primaquine alone','It does not provide adequate acute blood-stage treatment.'),('Doxycycline alone','It is not adequate initial therapy for severe malaria.')],
 'Rapid blood-stage parasite killing is essential', '**IV or appropriate parenteral artesunate is preferred for severe malaria.**',['Use the current weight- and setting-specific regimen.','Continue parenteral treatment for the indicated minimum and until an oral completion regimen is suitable.'], '**Organ support remains necessary despite effective parasite treatment.**',['Monitor glucose, fluid balance and respiratory or renal complications.','Arrange follow-on oral treatment and delayed-hemolysis follow-up.'],[['Initial drug','Artesunate'],['Support','Organ-specific critical care'],['Completion','Full appropriate oral course']],[WM,SM])
q('Two weeks after IV artesunate for severe malaria, a patient develops falling hemoglobin and biochemical hemolysis after parasitemia cleared. What should be considered?', 'Post-artesunate delayed hemolysis',[
 ('A phenomenon that proves persistent parasites in every case','Delayed hemolysis can occur after parasite clearance.'),('An indication to ignore all alternative hemolytic causes','Other causes still require assessment.'),('A reason never to use life-saving artesunate','The recognized risk does not remove its preferred severe-malaria role.')],
 'Recovery monitoring extends beyond the acute parasitemia phase', '**Delayed hemolysis can follow artesunate, especially with higher parasite burden.**',['Check hemoglobin and hemolysis markers.','Reassess microscopy when recurrence is a concern.'], '**Arrange the recommended follow-up.**',['CDC advises weekly monitoring for up to four weeks after initiation.','Provide transfusion and other support according to clinical need.'],[['Timing','Delayed after treatment'],['Assessment','Hemoglobin and hemolysis studies'],['Follow-up','Weekly up to four weeks in CDC guidance']],[SM],style='clinical_scenario')
q('After IV artesunate for severe falciparum malaria, why is an appropriate complete oral regimen still required?', 'Parenteral initial treatment must be followed by a full effective completion regimen to ensure cure',[
 ('One IV dose always guarantees eradication in every case','A complete validated treatment course is required.'),('The oral regimen is needed only to treat liver hypnozoites of falciparum','Falciparum does not form the vivax/ovale hypnozoite reservoir.'),('Any prophylactic drug dose is an equivalent completion course','Treatment and prevention regimens differ.')],
 'Initial stabilization and full parasitological treatment are distinct steps', '**Switch only when clinical and parasite-response criteria permit.**',['Use a currently recommended oral regimen appropriate to the species and setting.','Prior prophylaxis and resistance history affect selection.'], '**Check the current local schedule rather than assuming every ACT course is identical.**',['For example, CDC 2026 specifies an extended five-day artemether–lumefantrine follow-on for falciparum.','WHO and national implementation details should be identified explicitly.'],[['Initial phase','Parenteral artesunate'],['Completion','Full effective oral course'],['Schedule','Current setting-specific guidance']],[SM,WM])
q('Which malaria species classically require consideration of anti-hypnozoite treatment to prevent relapse?', 'P. vivax and P. ovale',[
 ('P. falciparum and P. malariae','They do not form the same dormant liver-stage reservoir.'),('P. knowlesi alone','It is not the classic hypnozoite-forming species.'),('Every Plasmodium species without exception','The liver-dormancy biology differs.')],
 'Blood-stage treatment does not eradicate every parasite stage', '**Vivax and ovale can persist as dormant liver hypnozoites.**',['Relapse can follow apparently successful blood-stage treatment.','Reinfection and blood-stage recrudescence are different mechanisms.'], '**Plan safe radical cure where appropriate.**',['Primaquine or eligible tafenoquine use requires G6PD and other eligibility assessment.','Pregnancy is an important contraindication to these drugs.'],[['Blood stage','Causes the acute febrile illness'],['Hypnozoite','Dormant vivax/ovale liver stage'],['Radical cure','Targets the relapse reservoir']],[UM,WM])
q('What must be assessed before using primaquine or tafenoquine for radical cure under CDC guidance?', 'Quantitative G6PD activity and the other drug-specific eligibility conditions',[
 ('A normal hemoglobin alone as proof of normal G6PD','Deficient patients can have a normal baseline hemoglobin.'),('ABO blood group as a substitute for enzyme testing','It does not measure G6PD activity.'),('A negative malaria rapid test as proof that the drugs are safe','It does not assess oxidant hemolysis risk.')],
 'Radical-cure drugs can cause severe oxidant hemolysis', '**G6PD assessment is essential for safe eligible use.**',['Testing during hemolysis or after transfusion can be misleading.','Tafenoquine has particularly important activity-threshold and eligibility requirements.'], '**Do not prescribe from a presumed normal status.**',['Use a specialist alternative plan if deficient.','Assess pregnancy and breastfeeding-related restrictions.'],[['Safety test','Quantitative G6PD'],['Risk','Oxidant hemolysis'],['Other conditions','Pregnancy, age and drug-specific criteria']],[UM,MQ])
q('A pregnant patient has treated vivax malaria and normal maternal G6PD activity. Why should primaquine radical cure still be deferred?', 'The fetal G6PD status is unknown and transplacental drug exposure can cause fetal hemolysis',[
 ('Normal maternal G6PD proves every fetus has normal activity','That inference is not valid.'),('Primaquine treats only blood-stage parasites and therefore has no role after delivery','It has a liver-stage radical-cure role when appropriate.'),('Pregnancy eliminates vivax relapse risk','The hypnozoite reservoir can persist.')],
 'Maternal safety testing does not establish fetal safety', '**Primaquine and tafenoquine are not used during pregnancy.**',['An appropriate suppressive strategy can be needed after acute treatment.','Postpartum radical cure considers maternal and relevant infant G6PD status and feeding.'], '**Use a pregnancy-specific malaria plan.**',['Treat acute disease promptly with an effective permitted regimen.','Arrange follow-up for recurrence and postpartum completion.'],[['Maternal G6PD','Not sufficient for fetal safety'],['Pregnancy','Defer 8-aminoquinoline radical cure'],['Later','Reassess safe postpartum treatment']],[UM],style='clinical_scenario')
q('Why is frequent glucose assessment important in severe malaria?', 'Hypoglycemia can result from the illness and can be worsened by some treatments such as quinine',[
 ('Altered consciousness always means cerebral sequestration and never hypoglycemia','A reversible metabolic cause must be checked.'),('A normal admission glucose guarantees stability throughout treatment','Glucose can change rapidly.'),('Hypoglycemia is impossible in pregnancy-associated malaria','Pregnancy can increase vulnerability.')],
 'Treatable metabolic abnormalities can mimic or worsen neurological disease', '**Measure glucose promptly in altered consciousness or seizures.**',['Repeat during severe illness and relevant therapy.','Correct low glucose immediately while continuing malaria treatment.'], '**Do not attribute every neurological sign to one mechanism.**',['Assess seizures, hypoxemia and other metabolic causes.','Use safe nutrition and monitoring within critical care.'],[['Risk','Illness-related hypoglycemia'],['Drug contribution','Quinine can increase insulin release'],['Action','Repeated measurement and prompt correction']],[WM,SM])
q('Which feature helps explain the high parasite burden and severe disease potential of falciparum malaria?', 'Infection of red cells across ages together with sequestration of infected cells in the microvasculature',[
 ('Exclusive infection of old red cells without vascular effects','That does not describe falciparum biology.'),('A dormant hypnozoite reservoir as the immediate cause of cerebral disease','Falciparum does not have that relapse reservoir.'),('Infection confined to platelets rather than red cells','The blood-stage parasite infects erythrocytes.')],
 'Parasite biology contributes to organ injury', '**Cytoadherence and sequestration impair microvascular function.**',['Peripheral density does not represent every sequestered parasite.','Hemolysis, inflammation and metabolic effects also contribute.'], '**Use both organ severity and parasitemia in assessment.**',['A single peripheral percentage is not the whole risk picture.','Treat severe manifestations urgently.'],[['Red-cell range','Broad'],['Microvasculature','Sequestration'],['Assessment','Clinical severity plus parasite measures']],[WM])
q('A severe malaria case needs urgent species confirmation, but reference PCR will take days. What is appropriate?', 'Use urgent microscopy/available rapid testing and start indicated treatment without waiting for reference PCR',[
 ('Delay severe-malaria treatment until the reference result returns','This can be fatal.'),('Use a normal platelet count as definitive exclusion','Blood-count findings are not diagnostic rule-out tests.'),('Choose radical cure from an unconfirmed species label without safety testing','Species and G6PD assessment still matter for that later decision.')],
 'Reference precision must not delay emergency treatment', '**Microscopy provides species clues and parasite density rapidly.**',['Rapid tests or NAAT can supplement where they return sooner.','Reference testing can resolve mixed or uncertain species.'], '**Treat the high-risk clinical state first.**',['Preserve a pretreatment sample when feasible.','Refine the regimen when reliable results become available.'],[['Urgent','Microscopy and rapid evidence'],['Reference','Resolves species/uncertainty'],['Treatment','Do not delay severe-disease care']],[MD,SM],style='clinical_scenario')
q('Vivax malaria recurs months after apparently adequate blood-stage treatment in a patient who received no radical cure and has had no new exposure. Which mechanism is likely?', 'Relapse from dormant liver hypnozoites',[
 ('A new mosquito inoculation is mandatory for every recurrence','Relapse can occur without reinfection.'),('The recurrence proves every blood-stage drug was resistant','A persisting liver reservoir is a separate mechanism.'),('Falciparum-specific sequestration as the explanation for every vivax relapse','That does not explain the hypnozoite phenomenon.')],
 'Recurrence categories have different implications', '**Relapse arises from reactivated liver hypnozoites.**',['Recrudescence reflects persisting blood-stage infection.','Reinfection requires a new exposure.'], '**Treat the acute recurrence and reassess safe radical cure.**',['Check quantitative G6PD and other eligibility conditions.','Review the original species, regimen and resistance context.'],[['Relapse','Dormant liver stage'],['Recrudescence','Residual blood-stage infection'],['Reinfection','New inoculation']],[UM,WM],style='clinical_scenario')
q('Which method is most useful for monitoring malaria parasite clearance during treatment?', 'Serial appropriately performed blood-smear microscopy with parasite-density assessment',[
 ('Persistence of a positive antigen rapid test alone','Antigen can remain detectable after parasite clearance.'),('HIV antibody testing','It does not assess malaria burden.'),('Platelet recovery alone as proof of eradication','Blood counts do not directly demonstrate parasite clearance.')],
 'The monitoring method must reflect the biological target', '**Microscopy can quantify evolving parasitemia.**',['Use appropriate serial timing in severe disease.','Rapid antigen tests are primarily diagnostic aids rather than quantitative cure monitors.'], '**Combine parasite trends with organ and clinical response.**',['Deterioration despite falling density can still require critical care.','Reassess species, resistance or alternative complications when response is abnormal.'],[['Microscopy','Parasite-density trend'],['Rapid antigen','Can persist after clearance'],['Clinical follow-up','Organ recovery and recurrence assessment']],[MD])

if __name__=='__main__':print('Tropical malaria block: '+str(len(rows))+' questions drafted')
